SELECT d.*, w.name AS windowName, c.name AS categoryName
FROM dish d
LEFT JOIN canteen_window w ON w.id = d.window_id
LEFT JOIN category c ON c.id = d.category_id

    AND d.window_id = #{windowId}
    AND d.category_id = #{categoryId}

        AND d.name LIKE CONCAT('%', #{keyword}, '%')


        AND w.merchant_id = #{merchantId}


ORDER BY d.id DESC

